 TextBox TableInput(FlowLayoutPanel panel,string key,string title){panel.Controls.Add(new Label{Text=title,Width=1050,Height=26,Tag="FullWidth",Font=ModernUi.Strong});var text=new TextBox{Multiline=true,ScrollBars=ScrollBars.Both,WordWrap=false,Width=1050,Height=200,Tag="FullWidth",Font=new Font("Consolas",9),MaxLength=0};Inputs.Add(key,text);panel.Controls.Add(text);return text;}
 void Action(FlowLayoutPanel panel,string caption,System.Action action){var button=new Button{Text=caption,AutoSize=true,Height=32};button.Click+=(s,e)=>{try{action();}catch(Exception error){MessageBox.Show(this,error.Message,caption);}};panel.Controls.Add(button);}
 readonly Dictionary<string,string> loadTitles=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);readonly HashSet<string> loadCombinations=new HashSet<string>(StringComparer.OrdinalIgnoreCase);string autoNote="";
 /* the Beams to check fill in by themselves (owner, 19 November 2026): beam lines are suggested as soon as the geometry is
    loaded and the dead / live service cases are entered from the STAAD load titles; the owner only reviews them */
 void AutoFill(){if(Restoring)return;var notes=new List<string>();int added=AutoSuggest();if(added>0)notes.Add(added+" beam line(s) suggested on Beams to check");
  try{var d=new BeamDeflectionData();StaadDisplacements.Displacements(d,displacements.Text,Value("DisplacementUnit"));var dead=new List<string>();var live=new List<string>();BeamDeflection.ClassifyCases(d.Cases(),loadTitles,loadCombinations,dead,live);int filled=0;
   foreach(DataGridViewRow r in groups.Rows){if(r.IsNewRow||Cell(r,CMembers)=="")continue;if(Cell(r,CDead)==""&&Cell(r,CLive)==""&&(dead.Count+live.Count)>0){r.Cells[CDead].Value=string.Join(", ",dead.Select(BeamDeflection.CaseId));r.Cells[CLive].Value=string.Join(", ",live.Select(BeamDeflection.CaseId));filled++;}}
   if(filled>0)notes.Add("load cases entered on "+filled+" line(s): dead "+(dead.Count==0?"(none found)":string.Join(", ",dead))+"; live "+(live.Count==0?"(none found)":string.Join(", ",live)));else if(dead.Count+live.Count==0&&d.Displacements.Count>0)notes.Add("no dead / live case could be recognised from the load titles; enter them on Beams to check");}catch(Exception){}
  if(notes.Count>0)autoNote="Automatic: "+string.Join("; ",notes)+". Review the lines and cases before you calculate.";}
 void Paste(TextBox target){if(!Clipboard.ContainsText())throw new Exception("The clipboard has no table text. Copy the STAAD table (including headings) first.");target.Text=Clipboard.GetText();}
 protected override bool OptionalSavedInput(string key){return key=="Sections"||key=="GeometrySource"||key=="ResultSource"||key=="Criterion"||key=="Duration";}
 BeamDeflectionData Data(){var data=new BeamDeflectionData();if(coordinates.Text.Trim()=="")throw new Exception("Node coordinates are missing. See the STAAD input requirements tab.");if(members.Text.Trim()=="")throw new Exception("Member incidences are missing. See the STAAD input requirements tab.");if(displacements.Text.Trim()=="")throw new Exception("Node displacements are missing. See the STAAD input requirements tab.");StaadDisplacements.Coordinates(data,coordinates.Text,Value("GeometryUnit"));StaadDisplacements.Members(data,members.Text);StaadDisplacements.Displacements(data,displacements.Text,Value("DisplacementUnit"));return data;}
 void RefreshLoaded(){var lines=new List<string>();
  if(coordinates.Text.Trim()==""&&members.Text.Trim()==""&&displacements.Text.Trim()==""){loaded.Text="Nothing loaded yet. Provide node coordinates, member incidences and node displacements.";return;}
  try{var d=new BeamDeflectionData();StaadDisplacements.Coordinates(d,coordinates.Text,Value("GeometryUnit"));lines.Add("Node coordinates: "+d.Nodes.Count+" nodes; unit from "+d.GeometryUnitSource+".");}catch(Exception ex){lines.Add("Node coordinates: "+ex.Message);}
  try{var d=new BeamDeflectionData();StaadDisplacements.Members(d,members.Text);lines.Add("Member incidences: "+d.Members.Count+" members.");}catch(Exception ex){lines.Add("Member incidences: "+ex.Message);}
  try{var d=new BeamDeflectionData();StaadDisplacements.Displacements(d,displacements.Text,Value("DisplacementUnit"));var cases=d.Cases().ToList();lines.Add("Node displacements: "+d.Displacements.Count+" rows, "+d.Displacements.Select(x=>x.Node).Distinct().Count()+" nodes, "+cases.Count+" load case(s): "+string.Join(", ",cases.Take(12))+(cases.Count>12?" ...":"")+"; unit from "+d.DisplacementUnitSource+".");}catch(Exception ex){lines.Add("Node displacements: "+ex.Message);}
  AutoFill();if(autoNote!="")lines.Add(autoNote);loaded.Text=string.Join("\r\n",lines);}
 static string N(double n){return n.ToString("0.#########",CultureInfo.InvariantCulture);}
 static string NodesText(BeamDeflectionData data,double unit,string name){return "Node\tX ("+name+")\tY ("+name+")\tZ ("+name+")\r\n"+string.Join("\r\n",data.Nodes.Values.OrderBy(n=>n.Id).Select(n=>n.Id+"\t"+N(n.X/unit)+"\t"+N(n.Y/unit)+"\t"+N(n.Z/unit)));}
 static string MembersText(BeamDeflectionData data){return "Beam\tNode A\tNode B\r\n"+string.Join("\r\n",data.Members.Values.OrderBy(m=>m.Id).Select(m=>m.Id+"\t"+m.A+"\t"+m.B));}
 static string ResultText(BeamDeflectionData data,double unit,string name){return "Node\tL/C\tX ("+name+")\tY ("+name+")\tZ ("+name+")\r\n"+string.Join("\r\n",data.Displacements.OrderBy(d=>d.Node).Select(d=>d.Node+"\t"+d.Case+"\t"+N(d.X/unit)+"\t"+N(d.Y/unit)+"\t"+N(d.Z/unit)));}
 void ApplyGeometry(BeamDeflectionData data,string file){string unit=Value("GeometryUnit");coordinates.Text=NodesText(data,StaadDisplacements.Unit(unit),unit);members.Text=MembersText(data);sections.Text=StaadDisplacements.SectionsText(data);geometrySource.Text=Path.GetFileName(file);if(data.ZUp)Inputs["Vertical"].Text="Z";}
 void ImportModel(){using(var dialog=new OpenFileDialog{Filter="STAAD model|*.std;*.txt|All files|*.*"})if(dialog.ShowDialog(this)==DialogResult.OK){var data=new BeamDeflectionData();supportNodes.Clear();string modelText=File.ReadAllText(dialog.FileName);BeamDeflection.LoadTitles(modelText,loadTitles,loadCombinations);StaadDisplacements.Model(data,modelText,Value("GeometryUnit"),supportNodes);if(data.Nodes.Count==0||data.Members.Count==0)throw new Exception("No expanded JOINT COORDINATES / MEMBER INCIDENCES found in the file.");ApplyGeometry(data,dialog.FileName);autoNote="Imported "+data.Nodes.Count+" nodes, "+data.Members.Count+" members and "+data.Sections.Count+" rectangular sections (unit from "+data.GeometryUnitSource+")"+(data.ZUp?"; SET Z UP: deflection direction set to global Z":"")+".";RefreshLoaded();}}
 void ImportAnl(){using(var dialog=new OpenFileDialog{Filter="STAAD analysis output|*.anl;*.txt|All files|*.*"})if(dialog.ShowDialog(this)==DialogResult.OK){var data=new BeamDeflectionData();string anlText=File.ReadAllText(dialog.FileName);BeamDeflection.LoadTitles(anlText,loadTitles,loadCombinations);StaadDisplacements.Anl(data,anlText,Value("GeometryUnit"),Value("DisplacementUnit"));if(data.Nodes.Count>0&&data.Members.Count>0)ApplyGeometry(data,dialog.FileName);string unit=Value("DisplacementUnit");displacements.Text=ResultText(data,StaadDisplacements.Unit(unit),unit);resultSource.Text=Path.GetFileName(dialog.FileName);RefreshLoaded();}}
 void ImportTable(TextBox target,string kind){using(var dialog=new OpenFileDialog{Filter="STAAD tables|*.csv;*.tsv;*.txt;*.xlsx;*.xlsm|All files|*.*"})if(dialog.ShowDialog(this)==DialogResult.OK){string ext=Path.GetExtension(dialog.FileName).ToLowerInvariant();var candidates=ext==".xlsx"||ext==".xlsm"?StaadSpreadsheet.Tables(dialog.FileName).Values.ToList():new List<string>{File.ReadAllText(dialog.FileName)};Exception last=null;
  foreach(string text in candidates){try{var data=new BeamDeflectionData();if(kind=="coordinates")StaadDisplacements.Coordinates(data,text,Value("GeometryUnit"));else if(kind=="members")StaadDisplacements.Members(data,text);else StaadDisplacements.Displacements(data,text,Value("DisplacementUnit"));target.Text=text;if(kind=="displacements")resultSource.Text=Path.GetFileName(dialog.FileName);else geometrySource.Text=Path.GetFileName(dialog.FileName);return;}catch(Exception error){last=error;}}
  throw new Exception("No usable "+kind+" table found. "+(last==null?"":last.Message));}}
 /* after a model is imported into an empty beam list, the beam lines are suggested automatically (the owner confirms them) */
 int AutoSuggest(){if(groups.Rows.Cast<DataGridViewRow>().Any(r=>!r.IsNewRow&&Cell(r,CMembers)!=""))return 0;try{var data=new BeamDeflectionData();StaadDisplacements.Coordinates(data,coordinates.Text,Value("GeometryUnit"));StaadDisplacements.Members(data,members.Text);int added=0;foreach(var item in BeamDeflection.SuggestGroups(data,Value("Vertical"))){groups.Rows.Add(item.Key,string.Join(", ",item.Value),Value("Criterion"),BeamDeflection.SpanTypes[0],"","","","","","","","");added++;}return added;}catch(Exception){return 0;}}
 void Suggest(){var data=new BeamDeflectionData();StaadDisplacements.Coordinates(data,coordinates.Text,Value("GeometryUnit"));StaadDisplacements.Members(data,members.Text);var found=BeamDeflection.SuggestGroups(data,Value("Vertical"));if(found.Count==0)throw new Exception("No straight beam lines with intermediate nodes were found perpendicular to global "+Value("Vertical")+".");
  var existing=new HashSet<string>(groups.Rows.Cast<DataGridViewRow>().Where(r=>!r.IsNewRow).Select(r=>Cell(r,CMembers)));int added=0;foreach(var item in found){string list=string.Join(", ",item.Value);if(existing.Contains(list))continue;groups.Rows.Add(item.Key,list,Value("Criterion"),BeamDeflection.SpanTypes[0],"","","","","","","","");added++;}
  MessageBox.Show(this,added+" beam line(s) added. They are split where columns/posts meet the beam. Confirm Support A/B, delete lines you do not need, and enter the dead and live load cases.","Suggest beam lines");}
 // Computes Ig/Ie and ρ' for the selected beam row from section data and the service moment Ma (NSCP 2015 Section 424.2.3.5).
 void IeCalculator(){groups.EndEdit();var row=groups.CurrentRow;if(row==null||row.IsNewRow)throw new Exception("Select a beam row first.");
  EffectiveInertiaInput start=null;try{if(Cell(row,CIe)!="")start=EffectiveInertia.Parse(Cell(row,CIe));}catch{}var section=start==null?RowSection(row):null;
  using(var form=new Form{Text="RC effective moment of inertia - NSCP 2015 Section 424.2.3.5",Width=560,Height=600,StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false,FormBorderStyle=FormBorderStyle.FixedDialog}){AppBrand.Apply(form);
   var panel=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,Padding=new Padding(14),AutoScroll=true};panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,62));panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,38));var boxes=new Dictionary<string,TextBox>();
   Func<EffectiveInertiaInput,string,string> init=(i,k)=>i==null?"":(k=="b"?i.B:k=="h"?i.H:k=="d"?i.D:k=="d'"?i.DPrime:k=="As"?i.As:k=="As'"?i.AsPrime:k=="fc'"?i.Fc:k=="Ma"?i.Ma:i.Lambda).ToString("R",CultureInfo.InvariantCulture);
   foreach(var f in new[]{new[]{"b","Web width b (mm)"},new[]{"h","Overall depth h (mm)"},new[]{"d","Effective depth d to tension steel (mm)"},new[]{"d'","Depth d' to compression steel (mm)"},new[]{"As","Tension steel As (mm²)"},new[]{"As'","Compression steel As' (mm², 0 if none)"},new[]{"fc'","Concrete strength fc' (MPa)"},new[]{"Ma","Service moment Ma at midspan, from STAAD (kN·m)"},new[]{"λ","Lightweight factor λ (1.0 normal weight)"}}){panel.Controls.Add(new Label{Text=f[1],AutoSize=true,Anchor=AnchorStyles.Left,Margin=new Padding(3,8,3,3)});var box=new TextBox{Width=160,Text=f[0]=="λ"&&start==null?"1":f[0]=="fc'"&&start==null?lastFc:init(start,f[0])};boxes[f[0]]=box;panel.Controls.Add(box);}
   if(section!=null){boxes["b"].Text=section[0].ToString("0.#",CultureInfo.InvariantCulture);boxes["h"].Text=section[1].ToString("0.#",CultureInfo.InvariantCulture);boxes["d"].Text=(section[1]-65).ToString("0.#",CultureInfo.InvariantCulture);boxes["d'"].Text="65";}
   var result=new Label{AutoSize=false,Width=500,Height=120,ForeColor=PowTheme.Muted,Text=(section!=null?"b and h are from the STAAD member section; d = h - 65 mm and d' = 65 mm are suggestions (40 mm cover + 10 mm tie + half of a 20 mm bar) - check them. ":"")+"Ma is the maximum service moment for the deflection being checked (for example dead + live). For continuous spans use the midspan section; NSCP permits averaging Ie for continuous members."};panel.Controls.Add(result);panel.SetColumnSpan(result,2);
   var buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=48,FlowDirection=FlowDirection.RightToLeft,Padding=new Padding(8)};var ok=new Button{Text="Use Ig/Ie and ρ'",AutoSize=true};var cancel=new Button{Text="Cancel",AutoSize=true,DialogResult=DialogResult.Cancel};buttons.Controls.AddRange(new Control[]{ok,cancel});string note=null;
   EffectiveInertiaInput current=null;EffectiveInertiaResult computed=null;Action run=()=>{Func<string,double> n=k=>StaadDisplacements.Number(boxes[k].Text);current=new EffectiveInertiaInput{B=n("b"),H=n("h"),D=n("d"),DPrime=boxes["d'"].Text.Trim()==""?0:n("d'"),As=n("As"),AsPrime=boxes["As'"].Text.Trim()==""?0:n("As'"),Fc=n("fc'"),Ma=n("Ma"),Lambda=n("λ")};computed=EffectiveInertia.Calculate(current);lastFc=boxes["fc'"].Text.Trim();result.ForeColor=PowTheme.Ink;result.Text=string.Join("\r\n",EffectiveInertia.Rows(current,computed).Skip(1).Select(r=>r[0]+": "+r[1]+";  "+r[2]));};
   note=result.Text;foreach(var b in boxes.Values)b.TextChanged+=(s,e)=>{try{run();}catch(Exception ex){computed=null;bool blank=boxes.Where(x=>x.Key!="d'"&&x.Key!="As'").Any(x=>x.Value.Text.Trim()=="");result.ForeColor=blank?PowTheme.Muted:Color.Firebrick;result.Text=blank?note:ex.Message;}};try{run();}catch(Exception){computed=null;}ok.Click+=(s,e)=>{try{run();form.DialogResult=DialogResult.OK;form.Close();}catch(Exception ex){result.ForeColor=Color.Firebrick;result.Text=ex.Message;}};
   form.Controls.Add(panel);form.Controls.Add(buttons);form.AcceptButton=ok;form.CancelButton=cancel;
   if(form.ShowDialog(this)==DialogResult.OK&&computed!=null){row.Cells[CStiffness].Value=computed.Ratio.ToString("F3",CultureInfo.InvariantCulture);row.Cells[CRho].Value=computed.RhoPrime.ToString("F5",CultureInfo.InvariantCulture);row.Cells[CIe].Value=EffectiveInertia.Basis(current);}}}
 static string lastFc="";
 /* b and h of the STAAD section shared by the members of a beam row (null when unknown or different) */
 double[] RowSection(DataGridViewRow row){try{var data=new BeamDeflectionData();StaadDisplacements.Sections(data,sections.Text);var ids=BeamDeflection.MemberIds(Cell(row,CMembers));double[] first=null;foreach(int id in ids){double[] s;if(!data.Sections.TryGetValue(id,out s))return null;if(first==null)first=s;else if(Math.Abs(first[0]-s[0])>.5||Math.Abs(first[1]-s[1])>.5)return null;}return first;}catch(Exception){return null;}}
 /* the RC Ie inputs of a row always give its Ig/Ie and ρ' (NSCP 2015 Section 424.2.3.5) */
 static void AutoEffectiveInertia(DataGridViewRow row){string basis=Cell(row,CIe);if(basis=="")return;var input=EffectiveInertia.Parse(basis);var r=EffectiveInertia.Calculate(input);row.Cells[CStiffness].Value=r.Ratio.ToString("F3",CultureInfo.InvariantCulture);row.Cells[CRho].Value=r.RhoPrime.ToString("F5",CultureInfo.InvariantCulture);}
 void ShowCases(){var d=new BeamDeflectionData();StaadDisplacements.Displacements(d,displacements.Text,Value("DisplacementUnit"));MessageBox.Show(this,string.Join("\r\n",d.Cases()),"Load cases in the displacement table");}
 static string Cell(DataGridViewRow row,int col){return Convert.ToString(row.Cells[col].Value,CultureInfo.InvariantCulture).Trim();}
 void Evaluate(){groups.EndEdit();var data=Data();latest.Clear();output.Rows.Clear();var errors=new List<string>();var vertical=Value("Vertical");bool service=((CheckBox)Inputs["ServiceBasis"]).Checked,supports=((CheckBox)Inputs["SupportsVerified"]).Checked;
  foreach(DataGridViewRow row in groups.Rows){if(row.IsNewRow||Cell(row,CMembers)=="")continue;for(int c=CSpan;c<=CStatus;c++)row.Cells[c].Value="";row.Cells[CStatus].Style.ForeColor=Color.Empty;
   try{AutoEffectiveInertia(row);string type=Cell(row,CType),crit=Cell(row,CCriterion);var input=new PhysicalBeamInput{Name=Cell(row,CName)==""?"B"+(row.Index+1):Cell(row,CName),Members=Cell(row,CMembers),Criterion=crit==""?Value("Criterion"):crit,SpanType=type==""?BeamDeflection.SpanTypes[0]:type,Start=Cell(row,CStart)==""?0:StaadDisplacements.Id(Cell(row,CStart)),End=Cell(row,CEnd)==""?0:StaadDisplacements.Id(Cell(row,CEnd)),DeadCases=Cell(row,CDead),LiveCases=Cell(row,CLive),RhoPrime=Cell(row,CRho)==""?0:StaadDisplacements.Number(Cell(row,CRho)),StiffnessFactor=Cell(row,CStiffness)==""?1:StaadDisplacements.Number(Cell(row,CStiffness)),CustomRatio=Cell(row,CCustom)==""?0:StaadDisplacements.Number(Cell(row,CCustom)),IeBasis=Cell(row,CIe),Xi=BeamDeflection.XiFor(Value("Duration")),Vertical=vertical,ServiceBasis=service,SupportsVerified=supports};
    var values=BeamDeflection.Calculate(data,input);latest.AddRange(values);var worst=values.OrderByDescending(v=>v.Utilization).First();row.Cells[CSpan].Value=worst.Span.ToString("F3",CultureInfo.InvariantCulture);row.Cells[CCheck].Value=worst.Check;row.Cells[CMax].Value=worst.MaximumMm.ToString("F2",CultureInfo.InvariantCulture);row.Cells[CLimit].Value="L/"+worst.LimitRatio.ToString("0",CultureInfo.InvariantCulture)+" = "+worst.LimitMm.ToString("F2",CultureInfo.InvariantCulture);row.Cells[CStatus].Value=worst.Status;row.Cells[CStatus].Style.ForeColor=worst.Exceeds?Color.Firebrick:worst.Qualified?PowTheme.Teal:Color.DarkGoldenrod;
    foreach(var value in values)output.Rows.Add(BeamDeflectionReport.SummaryRow(value));}
   catch(Exception error){row.Cells[CStatus].Value=error.Message;row.Cells[CStatus].Style.ForeColor=Color.Firebrick;errors.Add("Row "+(row.Index+1)+": "+error.Message);}}
  if(errors.Count>0)throw new Exception(string.Join("\r\n",errors));if(latest.Count==0)throw new Exception("Add at least one beam on the Beams to check tab (STAAD member IDs).");
  summary=new BeamDeflectionSummary{GeometrySource=geometrySource.Text,ResultSource=resultSource.Text,GeometryUnit=data.GeometryUnitSource,DisplacementUnit=data.DisplacementUnitSource,Vertical=vertical,ZUp=vertical=="Z",ServiceBasis=service,SupportsVerified=supports,Nodes=data.Nodes.Count,Members=data.Members.Count,Cases=data.Cases().ToList(),Duration=Value("Duration")};}
 protected override string BuildReport(){Evaluate();return BeamDeflectionReport.Text(summary,latest);}
 protected override EngineeringReport BuildEngineeringReport(){Evaluate();return BeamDeflectionReport.Create(summary,latest);}
 protected override CalculationDocument BuildDocument(){var report=BuildEngineeringReport();var document=CalculationDocument.FromEngineering(report);BeamDeflectionReport.AddShapeSheets(document,latest);return document;}
 protected override void WriteAdditionalState(XmlElement root){var table=root.OwnerDocument.CreateElement("BeamGroups");table.SetAttribute("version","3");root.AppendChild(table);foreach(DataGridViewRow row in groups.Rows)if(!row.IsNewRow&&Cell(row,CMembers)!=""){var item=root.OwnerDocument.CreateElement("Beam");for(int c=0;c<Keys.Length;c++)item.SetAttribute(Keys[c],Cell(row,c));table.AppendChild(item);}}
 // Version 2 sheets (v1.4.63 first release) used L/n and one case list: they open as Custom limit rows with those cases as live cases.
 protected override void ReadAdditionalState(XmlElement root){var table=root["BeamGroups"];string version=table==null?"":table.GetAttribute("version");if(version!="2"&&version!="3")throw new Exception("Missing or unsupported beam list in the saved sheet.");var rows=new List<object[]>();
  foreach(XmlElement row in table.SelectNodes("Beam")){object[] values;if(version=="3")values=Keys.Select(k=>(object)row.GetAttribute(k)).ToArray();else values=new object[]{row.GetAttribute("c0"),row.GetAttribute("c1"),BeamDeflection.Custom,row.GetAttribute("c2"),row.GetAttribute("c3"),row.GetAttribute("c4"),"",row.GetAttribute("c5"),"","",row.GetAttribute("c6"),""};
   if(!BeamDeflection.SpanTypes.Contains(Convert.ToString(values[CType])))values[CType]=BeamDeflection.SpanTypes[0];if(!BeamDeflection.CriterionNames.Contains(Convert.ToString(values[CCriterion])))throw new Exception("Saved sheet uses an unknown deflection criterion: "+values[CCriterion]);rows.Add(values);}
  bool was=Restoring;Restoring=true;try{groups.Rows.Clear();foreach(var values in rows)groups.Rows.Add(values);}finally{Restoring=was;}}
 protected override void AfterRestore(){RefreshLoaded();}
}
